UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Paramedian Approach — Technique","body":"**Why Paramedian?** [2][12]\n• **30-40% higher first-attempt success** than midline\n• Avoids supraspinous and interspinous ligaments (often calcified in elderly)\n• Does NOT require full spine flexion\n• Wider interlaminar space than interspinous space\n• Lower PDPH incidence (oblique track creates flap-valve closure)\n• Less back pain post-procedure\n\n**Best for:**\n• Age >50 (calcified ligaments)\n• Failed midline attempts\n• Severe degenerative changes\n• Kyphosis or scoliosis\n• Patients who cannot flex spine\n• Sitting position (where full flexion is limited)\n\n**Not recommended for:**\n• Severely obese patients (longer needle path, difficult manipulation)\n\n**Layers traversed (paramedian):**\n1. Skin\n2. Subcutaneous tissue\n3. Paraspinal muscles\n4. **Ligamentum flavum** (main resistance)\n5. Epidural space\n6. **Dura mater**\n7. Subarachnoid space [2][12]","citation":[2,12],"next":"lp-paramedian-insertion","summary":"Paramedian: enter 1-1.5cm lateral to midline, angle medially toward spinous process","skippable":true}'::jsonb
